# Real desktop acceptance of a known 12x20 numeric grid; no business dataset is modified.
# Input: HDFSTUDIO_GRID_SAMPLE (fixture generated by grid_analysis_verify.py).
# Output: logs/S4-GridAnalysis/desktop-configuration-time with clipboard TSV and screenshots.
param([ValidateSet('Debug','Release')][string]$Configuration='Release',[string]$Executable='',[string]$RunLabel='')
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient,UIAutomationTypes,System.Windows.Forms,System.Drawing
Add-Type -TypeDefinition @"
using System;using System.Runtime.InteropServices;
public class GridMouse {
 [DllImport("user32.dll")] public static extern bool SetCursorPos(int x,int y);
 [DllImport("user32.dll")] public static extern void mouse_event(uint f,uint x,uint y,uint d,IntPtr e);
 [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h,int c);
 [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
 [DllImport("user32.dll")] public static extern void keybd_event(byte v,byte s,uint f,IntPtr e);
 [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);
 public static void Front(IntPtr h){ShowWindow(h,3);keybd_event(0x12,0,0,IntPtr.Zero);keybd_event(0x12,0,2,IntPtr.Zero);SetForegroundWindow(h);}
 public static void Click(int x,int y,bool right){SetCursorPos(x,y);mouse_event(right?8u:2u,0,0,0,IntPtr.Zero);mouse_event(right?16u:4u,0,0,0,IntPtr.Zero);}
 public static void Drag(int x,int y,int xx,int yy){SetCursorPos(x,y);mouse_event(2,0,0,0,IntPtr.Zero);for(int i=1;i<=12;i++){SetCursorPos(x+(xx-x)*i/12,y+(yy-y)*i/12);System.Threading.Thread.Sleep(25);}mouse_event(4,0,0,0,IntPtr.Zero);}
}
"@
$root=Split-Path $PSScriptRoot -Parent
if(-not $Executable){$Executable=Join-Path $root "build/output/$Configuration/HDFStudio.exe"}
if(-not $RunLabel){$RunLabel=$Configuration}
$sample=$env:HDFSTUDIO_GRID_SAMPLE
if(-not $sample -or -not(Test-Path -LiteralPath $sample)){throw 'Set HDFSTUDIO_GRID_SAMPLE to the generated fixture'}
$before=(Get-FileHash -LiteralPath $sample -Algorithm SHA256).Hash
$log=Join-Path $root ('logs/S4-GridAnalysis/desktop-'+$RunLabel+'-'+(Get-Date -Format yyyyMMdd-HHmmss))
$null=New-Item -ItemType Directory -Force $log
$uia=[Windows.Automation.AutomationElement]
$results=@();$widths=@();$process=$null;$window=$null
function FindName($container,$name){,@($container.FindAll([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.PropertyCondition]::new($uia::NameProperty,$name)))}
function Check($name,$pass){$script:results+=[pscustomobject]@{check=$name;pass=[bool]$pass};"$(Get-Date -Format s) $name : $pass";if(-not $pass){throw $name}}
function Click($element,$right=$false){if(-not $element){throw 'UI element missing'};$r=$element.Current.BoundingRectangle;if($r.IsEmpty -or $element.Current.IsOffscreen){throw ('Offscreen: '+$element.Current.Name)};[GridMouse]::Click([int]($r.X+$r.Width/2),[int]($r.Y+$r.Height/2),$right);Start-Sleep -Milliseconds 180}
function Invoke($element){if(-not $element){throw 'Invoke target missing'};$pattern=$null;if($element.TryGetCurrentPattern([Windows.Automation.InvokePattern]::Pattern,[ref]$pattern)){$pattern.Invoke();Start-Sleep -Milliseconds 150}else{Click $element}}
function Shot($name){$r=[Windows.Forms.SystemInformation]::VirtualScreen;$b=[Drawing.Bitmap]::new($r.Width,$r.Height);$g=[Drawing.Graphics]::FromImage($b);try{$g.CopyFromScreen($r.X,$r.Y,0,0,$b.Size);$b.Save((Join-Path $log ($name+'.png')))}finally{$g.Dispose();$b.Dispose()}}
function CopyCells($name){[Windows.Forms.SendKeys]::SendWait('^c');Start-Sleep -Milliseconds 150;$text=[Windows.Forms.Clipboard]::GetText();[IO.File]::WriteAllText((Join-Path $log ($name+'.tsv')),$text,[Text.UTF8Encoding]::new($false));return $text}
try {
 $env:QT_LOGGING_TO_CONSOLE='1'
 $process=Start-Process $Executable -ArgumentList ('"'+$sample+'"') -PassThru -RedirectStandardError (Join-Path $log 'qt-plugin.log')
 $processHandle=$process.Handle
 $clock=[Diagnostics.Stopwatch]::StartNew()
 do{
  $condition=[Windows.Automation.PropertyCondition]::new($uia::ProcessIdProperty,$process.Id)
  $windows=@($uia::RootElement.FindAll([Windows.Automation.TreeScope]::Children,$condition))
  $window=@($windows|Where-Object {(FindName $_ 'analysis').Count-gt 0})|Select-Object -First 1
  if($window){break};Start-Sleep -Milliseconds 200
 }while($clock.ElapsedMilliseconds-lt 20000)
 Check 'Dataset ready' ($null-ne $window)
 [GridMouse]::Front([IntPtr]$window.Current.NativeWindowHandle);Start-Sleep -Milliseconds 400
 foreach($mode in @('Data Grid (decoded to real)...','Stored Grid (raw value)...','Both Grids (decoded and raw)...')){
  Click (FindName $window 'analysis')[0] $true
  $menuItem=(FindName $uia::RootElement $mode)[0]
  if(-not $menuItem){throw 'Grid menu item missing'}
  $menuRect=$menuItem.Current.BoundingRectangle
  [GridMouse]::SetCursorPos([int]($menuRect.X+$menuRect.Width/2),[int]($menuRect.Y+$menuRect.Height/2))|Out-Null
  Start-Sleep -Milliseconds 200
  [Windows.Forms.SendKeys]::SendWait('{ENTER}');Start-Sleep -Milliseconds 400
  $clock.Restart()
  do{
   $tables=@((FindName $window 'Data grid cells')|Where-Object {-not $_.Current.IsOffscreen})
   if($tables.Count){break};Start-Sleep -Milliseconds 100
  }while($clock.ElapsedMilliseconds-lt 5000)
  $table=$tables[-1]
  Check ($mode+' uses shared grid') ($null-ne $table)
  $grid=$table.GetCurrentPattern([Windows.Automation.GridPattern]::Pattern)
  $columnCount=if($mode.StartsWith('Both')){40}else{20}
  Check ($mode+' shape') ($grid.Current.RowCount-eq 12 -and $grid.Current.ColumnCount-eq $columnCount)
  Check ($mode+' auto-fit visible') ((FindName $window 'Auto-fit columns').Count-gt 0)
  $cell=$grid.GetItem(1,1);Click $cell
  $single=CopyCells 'single'
  Check ($mode+' click and copy') ($single-eq $(if($mode.StartsWith('Both')){'100'}else{'100.125'}))
  $start=$grid.GetItem(1,1).Current.BoundingRectangle;$end=$grid.GetItem(3,4).Current.BoundingRectangle
  [GridMouse]::Drag([int]($start.X+$start.Width/2),[int]($start.Y+$start.Height/2),[int]($end.X+$end.Width/2),[int]($end.Y+$end.Height/2));Start-Sleep -Milliseconds 150
  $name=if($mode.StartsWith('Both')){'both'}elseif($mode.StartsWith('Stored')){'stored'}else{'decoded'}
  $block=CopyCells $name
  Check ($mode+' drag selects 12 cells') ((FindName $window 'Selected: 12 cells').Count-gt 0 -and ($block-split "`n").Count-eq 3)
  Check ($mode+' compact numeric columns') ($start.Width-ge 24 -and $start.Width-lt 100)
  $widths+=[pscustomobject]@{mode=$name;width_pixels=$start.Width;text=$single;header_rows=$(if($mode.StartsWith('Both')){2}else{1})}
  Shot $name
  [Windows.Forms.SendKeys]::SendWait('^{F4}');Start-Sleep -Milliseconds 250
 }
 Check 'Fixture unchanged' ((Get-FileHash -LiteralPath $sample -Algorithm SHA256).Hash-eq $before)
 $null=[GridMouse]::PostMessage([IntPtr]$window.Current.NativeWindowHandle,0x10,[IntPtr]::Zero,[IntPtr]::Zero)
 Check 'Normal process exit' ($process.WaitForExit(5000))
  $process.Refresh();Check 'Exit code zero' ($process.ExitCode-eq 0)
  $widths|ConvertTo-Json|Set-Content (Join-Path $log 'width-measurements.json') -Encoding UTF8
 [pscustomobject]@{status='PASS';checks=$results.Count;sample_sha256=$before;clipboard_files=@('decoded.tsv','stored.tsv','both.tsv')}|ConvertTo-Json|Set-Content (Join-Path $log 'summary.json') -Encoding UTF8
}catch{
 try{Shot 'failure'}catch{}
 if($window){try{$window.FindAll([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.Condition]::TrueCondition)|ForEach-Object {$_.Current.Name}|Out-File (Join-Path $log 'controls.txt') -Encoding utf8}catch{}}
 Get-Process HDFStudio -ErrorAction SilentlyContinue|Select-Object Id,Responding,WorkingSet64,MainWindowTitle|ConvertTo-Json|Set-Content (Join-Path $log 'processes.json') -Encoding UTF8
 throw
}finally{
 $results|ConvertTo-Json|Set-Content (Join-Path $log 'results.json') -Encoding UTF8
 if($process -and -not $process.HasExited){$null=$process.CloseMainWindow();if(-not $process.WaitForExit(3000)){Stop-Process -Id $process.Id}}
}
